const controlsData = $input.item.json.response;
const prev = $('Store Pages Data1').item.json;

if (!controlsData || !Array.isArray(controlsData)) {
  throw new Error('Controls data missing');
}

const pendingSigner = prev.registerData.signatories?.find(s => s.signStatus === 'Pending');
if (!pendingSigner) {
  throw new Error('No pending signer found');
}

const pendingControls = controlsData.filter(c => 
  c.email === pendingSigner.email && 
  c.controlStatus === 'Pending' &&
  c.isSignature
);

if (!pendingControls.length) {
  throw new Error('No pending signature controls found');
}

const documentContext = { 
  signAuth: prev.signAuth, 
  registerSignID: prev.registerData.registerSignID, 
  masterDocID: prev.registerData.primaryDocs[0].masterDocID, 
  docName: prev.registerData.primaryDocs[0].docName, 
  docPath: prev.registerData.primaryDocs[0].docPath, 
  totalPages: prev.pages.length, 
  signatoryID: pendingSigner.signatoriesID, 
  signatoryName: pendingSigner.name, 
  signatoryEmail: pendingSigner.email, 
  signatureColor: pendingSigner.signatureColor, 
  controlsToSign: pendingControls.map(c => ({
    controlLocationID: c.controlLocationID, 
    pageNumber: c.pagesOrder, 
    pageName: c.pagesName, 
    positionX: c.controlLocationX, 
    positionY: c.controlLocationY, 
    width: c.width, 
    height: c.height 
  })), 
  pages: prev.pages.map(p => ({
    pageID: p.masterDocPagesID, 
    pageName: p.pagesName, 
    pageOrder: p.pagesOrder, 
    pagePath: p.pagesPath 
  })), 
  initiatorEmail: prev.registerData.createdBy, 
  initiatorName: prev.registerData.createdByName 
};

console.log('Document context built successfully');
return { json: documentContext };

