const messageData = $('Route Message Type1').item.json;
const aiResponse = $input.item.json.output || 'Thank you for your message about IAmSigner.';

return { 
  json: { 
    aiResponse: aiResponse,
    isSigningLink: messageData.isSigningLink,
    isSigningRequest: messageData.isSigningRequest,
    originalMessage: messageData.message,
    timestamp: new Date().toISOString()
  } 
