// Get message from webhook body
const body = $input.item.json.body || $input.item.json;
const chatMessage = body.chatInput || body.input || body.message || '';
const lowerMessage = chatMessage.toLowerCase().trim();

// Helper function for word boundary matching
const hasKeyword = (text, keyword) => {
  // Escape special regex characters in keyword
  const escapedKeyword = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = new RegExp(`\\b${escapedKeyword}\\b`, 'i');
  return pattern.test(text);
};

// Check if message contains a signing link
const urlPattern = /\/SignNow\/id\/([^\s\/]+)/;
const isSigningLink = urlPattern.test(chatMessage);

// Check for signing request keywords (exact phrase matching)
const signingKeywords = ['sign it', 'signit', 'sign this', 'apply signature', 'sign document', 'sign now', 'complete signing', 'please sign'];
const isSigningRequest = signingKeywords.some(keyword => hasKeyword(lowerMessage, keyword));

// Check for summary request keywords (exact phrase matching)
const summaryKeywords = ['detail summary', 'detailed summary', 'summarize', 'summarise', 'summary of', 'tell me about', 'explain the document', 'what does this document say', 'document details', 'analyze the document', 'provide details'];
const isSummaryRequest = summaryKeywords.some(keyword => hasKeyword(lowerMessage, keyword));

// Check for questions about IAmSigner (word boundary matching)
const iamSignerKeywords = ['iamsigner', 'esign', 'electronic signature', 'verify', 'how to', 'what is', 'help', 'feature', 'api'];
const isQuestion = iamSignerKeywords.some(keyword => hasKeyword(lowerMessage, keyword)) ||
                  lowerMessage.includes('iamsigner') || 
                  lowerMessage.includes('electronic signature');

// Check if it's a greeting (exact word matching)
const greetings = ['hello', 'hi', 'hey', 'greetings'];
const isGreeting = greetings.some(greet => hasKeyword(lowerMessage, greet));

// Check for common questions
const commonQuestions = lowerMessage.includes('?') || 
                       lowerMessage.startsWith('what') ||
                       lowerMessage.startsWith('how') ||
                       lowerMessage.startsWith('when') ||
                       lowerMessage.startsWith('where') ||
                       lowerMessage.startsWith('why') ||
                       lowerMessage.startsWith('can you');

return { 
  json: { 
    message: chatMessage,
    isSigningLink: isSigningLink,
    isSigningRequest: isSigningRequest,
    isSummaryRequest: isSummaryRequest,
    isQuestion: isQuestion || commonQuestions,
    isGreeting: isGreeting,
    requiresResponse: isSigningLink || isQuestion || commonQuestions || isGreeting || isSigningRequest || isSummaryRequest,
    timestamp: new Date().toISOString(),
    sessionId: body.sessionId || `session_${Date.now()}`
  } 
};

const context = $input.item.json;

// Validate that we have the necessary context
if (!context || !context.signAuth) {
  throw new Error('❌ No document context found. Please provide a signing link first by sharing the document link.');
}

if (!context.url || !context.docName) {
  throw new Error('❌ Document information incomplete. Please verify the signing link again.');
}

console.log('Document context retrieved for summary:', context.docName);

return {
