    totalPages: context.totalPages || 0,
    initiatorEmail: context.initiatorEmail || 'N/A',
    initiatorName: context.initiatorName || 'N/A'
  }
};

const sessionId = $('Route Message Type1').first().json.sessionId;

return {
  json: {
    sessionId: sessionId
  }
};

// NEW NODE: Check Signing Requirements
const data = $input.item.json;
const message = data.message.toLowerCase().trim();
const isSigningRequest = data.isSigningRequest;
const isSummaryRequest = data.isSummaryRequest;
const isSigningLink = data.isSigningLink;

// Check for signing/summary requests WITHOUT a link
if ((isSigningRequest || isSummaryRequest) && !isSigningLink) {

  // Determine the action type for better messaging
  const actionType = isSigningRequest ? 'sign' : 'get a summary of';
  const actionEmoji = isSigningRequest ? '✍️' : '📊';

  return {
    json: {
      // User-friendly message with clear instructions
      output: `📋 **Ready to ${actionType.toUpperCase()}?**\n\n> To ${actionType} a document, please **share the signing link** first.\n\n### **How It Works:**\n1️⃣ **Copy** your IAmSigner signing link\n2️⃣ **Paste** it here in the chat\n3️⃣ I'll **verify** the document\n4️⃣ Then say **"${isSigningRequest ? 'sign it' : 'detail summary'}"**\n\n### **Need Help Finding Your Link?**\n• Check your email from IAmSigner\n• Look for a link containing **/SignNow/id/**\n• Example: \`https://demo.iamsigner.com/SignNow/id/abc123\`\n\nOnce you share the link, I'll help you ${actionType} the document! ${actionEmoji}`,

      // Flags to prevent further processing
      skipToEnd: true,
      isEarlyExit: true,
      originalMessage: data.message,
      sessionId: data.sessionId,
      timestamp: new Date().toISOString()
    }
  };
}

// If user provided a link OR it's not a signing/summary request, continue normally
return data;

// NEW NODE: Format Early Response
const data = $input.item.json;
